target={1,2,9}
# Identify all 4-neighbor components with target palette; ignore control top-left bbox.
seen=set(); erase=set(); chosen=[]
for r in range(H):
 for c in range(W):
  if grid[r][c]!=7 and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); pts=[]
   while q:
    x,y=q.pop(); pts.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     nx,ny=x+dx,y+dy
     if 0<=nx<H and 0<=ny<W and grid[nx][ny]!=7 and (nx,ny) not in seen:
      seen.add((nx,ny));q.append((nx,ny))
   colors={grid[x][y] for x,y in pts if grid[x][y] not in (0,7)}
   bbox=(min(x for x,y in pts),max(x for x,y in pts),min(y for x,y in pts),max(y for x,y in pts))
   if target.issubset(colors) and not (bbox[0]==0 and bbox[2]==0):
    chosen.append((bbox,colors,len(pts)));erase.update(pts)
out=[row[:] for row in grid]
for r,c in erase: out[r][c]=7
import json
print(chosen)
print(json.dumps(out,separators=(',',':')))
